import { Player } from "../utils/types";
import {Container, ListGroup} from "react-bootstrap";
import { useEffect, useState } from "react";
import { getAllUsers } from "../utils/get_data";
import TableEntry from "./table_entry";

const Ranking: React.FC<{ isScreenSmall: Boolean }> = ({isScreenSmall}) => {
    const [allPlayers, setAllPlayers] = useState<Player[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAllUsers = async () => {
            setLoading(true);
            try {
                const users = await getAllUsers();
                const sortedUsers = users.sort((a, b) => {
                    if (a.ranking === null && b.ranking === null) {
                        return b.score - a.score;
                    } else if (a.ranking === null) {
                        return 1;
                    } else if (b.ranking === null) {
                        return -1;
                    }
                    return a.ranking - b.ranking;
                });
                setAllPlayers(sortedUsers);
            } catch (error) {
                console.error("Error fetching users:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchAllUsers();

        const intervalId = setInterval(fetchAllUsers, 30000);

        return () => clearInterval(intervalId);
    }, []);

    if (loading) {
        return <div>Loading...</div>;
    }

    return(
        <Container className={isScreenSmall ? "d-flex flex-column p-0" : "d-flex flex-column"}>
            <ListGroup>
                {allPlayers.map((player) => (
                    <TableEntry
                        key={player.uid}
                        player={player}
                        isScreenSmall={isScreenSmall}
                    />
                ))}
            </ListGroup>
        </Container>
    )
}

export default Ranking;