import LeftSide from "./login_left_side";
import {Alert, Button, Col, Container, Form, Row} from "react-bootstrap";
import ScreenResize from "../utils/screen_resize";
import { useState} from "react";
import { auth } from "../firebaseConfig";
import { sendPasswordResetEmail } from "firebase/auth";
import { useNavigate } from "react-router-dom";

const ResetPassword = () => {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [validated, setValidated] = useState(false);
    const [resetAlert, setResetAlert] = useState('');
    const isScreenSmall = ScreenResize(900);

    const handlePasswordReset = () => {
        if (!email) {
            setResetAlert("Inserisci la tua email per il reset della password");
            return;
        }
        sendPasswordResetEmail(auth, email)
            .then(() => setResetAlert("Email per il reset della password inviata. Controlla la tua casella di posta."))
            .catch((error) => setResetAlert("Errore durante il reset della password. Riprovare più tardi."));
    };

    return (
        <Container fluid className="p-0 d-flex" style={{height: '100vh'}}>
            <Row className="flex-grow-1 p-0 m-0" style={{height:"100%"}}>
                <LeftSide/>
                <Col className="p-0 d-flex flex-column" sm={isScreenSmall ? 12 : 6}>
                    <Row fluid className="d-flex p-0 m-0 flex-grow-1 align-items-center" style={{backgroundColor: isScreenSmall ? '#2f7157' : 'white'}}>
                        <Row className="align-items-center justify-content-center d-flex p-0 m-0">
                            <svg height="40" width="100%">
                                <line x1="0" y1="100%" x2="100%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 16 }} />
                            </svg>
                            <svg height="100" width="10">
                                <line x1="50%" y1="0%" x2="50%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 10 }} />
                            </svg>
                        </Row>
                        <Form noValidate className="" validated={validated} style={{width:"100%"}} onSubmit={handlePasswordReset}>
                            <Col className="d-flex justify-content-center mx-5 mb-4">
                                <h2 className={isScreenSmall ? "mt-5 my-font" : "mt-2 my-font"} style={{color: isScreenSmall ? 'white' : '#2f7157'}}>
                                    Inserisci l'email del tuo profilo per il reset della password
                                </h2>
                            </Col>

                            <Row className="justify-content-center mx-5 mt-3">
                                <Col sm={8}>
                                    {resetAlert && <Alert variant='info' onClose={() => setResetAlert('')} dismissible>{resetAlert}</Alert>}
                                    <Form.Group id="formBasicEmail">
                                        <Form.Label className="my-font" style={{color: isScreenSmall ? 'white' : '#2f7157'}}>Email</Form.Label>
                                        <Form.Control
                                            type="text"
                                            placeholder="Inserisci email"
                                            value={email}
                                            style={{
                                                borderRadius: "40px",
                                                border: "solid",
                                                borderWidth: "2px",
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}
                                            onChange={(e) => setEmail(e.target.value)}
                                            required
                                        />
                                    </Form.Group>
                                </Col>
                            </Row>
                            <Row className="justify-content-center mx-5 mt-3 mb-4">
                                <Col sm={8} className="d-flex justify-content-center">
                                    <Button className="my-button-login mt-4" variant="primary" type="submit"
                                            style={{
                                                width: '50%',
                                                minHeight: '40px',
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}>
                                        <h5 className="my-font" style={{ pointerEvents: "none" }}>
                                            Conferma
                                        </h5>
                                    </Button>
                                </Col>
                            </Row>
                            <Row className="justify-content-center mx-5 mt-3 mb-4">
                                <Col sm={8} className="d-flex justify-content-center">
                                    <Button className="my-button-login" variant="primary"
                                            style={{
                                                width: '50%',
                                                minHeight: '40px',
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}
                                            onClick={() => navigate("/")}>
                                        <h5 className="my-font" style={{ pointerEvents: "none" }}>
                                            Indietro
                                        </h5>
                                    </Button>
                                </Col>
                            </Row>
                        </Form>
                        <Row className="align-items-center justify-content-center d-flex p-0 m-0">
                            <svg height="100" width="10">
                                <line x1="50%" y1="0%" x2="50%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 10 }} />
                            </svg>
                            <svg height="40" width="100%">
                                <line x1="0" y1="0%" x2="100%" y2="0%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 16 }} />
                            </svg>
                        </Row>
                    </Row>
                </Col>
            </Row>
        </Container>
    )
}

export default ResetPassword;