import {Match, Player} from "../utils/types";
import {Card, Col, Row} from "react-bootstrap";
import React, {useEffect, useState} from "react";
import "./account.css"
import {getUser} from "../utils/get_data";
import {myGreen} from "../utils/utility";

interface MatchCardProps {
    player: Player; // Potrebbe essere player1 o player2
    match: Match;
}

const MatchCard: React.FC<MatchCardProps> = ({ player, match }) => {
    const [opponent, setOpponent] = useState<Player | null>(null);
    const isPlayer1 = player.uid === match.player1ID; // Verifica se il giocatore passato è player1

    useEffect(() => {
        const fetchOpponent = async () => {
            const opponentID = isPlayer1 ? match.player2ID : match.player1ID;
            const fetchedOpponent = await getUser(opponentID);
            if (fetchedOpponent) {
                setOpponent(fetchedOpponent);
            } else {
                console.error("Errore nel recupero dell'avversario");
            }
        };

        fetchOpponent();
    }, [player, match, isPlayer1]);

    // Estrarre i punteggi corretti in base a chi è il player passato
    const sets = match.score.split(" ");
    let playerScores: string[] = [];
    let opponentScores: string[] = [];
    let setWinners: number[] = [];

    sets.forEach((set) => {
        const [score1, score2] = set.split("-").map((s) => parseInt(s));
        if (isPlayer1) {
            playerScores.push(score1.toString());
            opponentScores.push(score2.toString());
            setWinners.push(score1 > score2 ? 1 : 2);
        } else {
            playerScores.push(score2.toString());
            opponentScores.push(score1.toString());
            setWinners.push(score2 > score1 ? 1 : 2);
        }
    });

    if (!opponent) {
        return null;
    }

    return (
        <Col xs={12}>
            <Col className="card-wrapper">
                <Card className="pb-2" style={{borderColor: "transparent"}}>
                    <Card.Body className="mx-5 p-0">
                        <Row className="d-flex justify-content-center mb-3">
                            <Col xs={12} className="d-flex justify-content-center p-0">
                                <p className="my-font m-0 text-start" style={{ fontSize: "1em" }}>
                                    {match.date}
                                </p>
                            </Col>
                        </Row>
                        <Row className="d-flex justify-content-between mb-2 flex-nowrap">
                            <Col xs={2} className="d-flex align-items-center p-0 ms-2">
                                <p className="m-0">
                                    {(isPlayer1 ? match.p1Score : match.p2Score) >= 0
                                        ? `+${isPlayer1 ? match.p1Score : match.p2Score}`
                                        : isPlayer1 ? match.p1Score : match.p2Score}
                                </p>
                            </Col>
                            <Col xs={5} className="d-flex align-items-center p-0 ms-1">
                                <p className="my-font m-0 text-start" style={{ fontSize: "1.2em" }}>
                                    {player.name} <br/>{player.surname}
                                </p>
                            </Col>
                            <Col xs={5} className="d-flex align-items-center p-0">
                                {playerScores.map((score, index) => (
                                    <p
                                        key={index}
                                        className="me-2 mb-0"
                                        style={{
                                            fontWeight: setWinners[index] === 1 ? "bold" : "",
                                            color: setWinners[index] === 1 ? myGreen : "black",
                                        }}
                                    >
                                        {score}
                                    </p>
                                ))}
                            </Col>
                        </Row>
                        <Col xs={12}>
                            <div className="my-2 mx-1" style={{ height: "2px", backgroundColor: myGreen }}></div>
                        </Col>
                        <Row className="d-flex justify-content-between flex-nowrap">
                            <Col xs={2} className="d-flex align-items-center p-0 ms-2">
                                <p className="m-0">
                                    {(isPlayer1 ? match.p2Score : match.p1Score) >= 0
                                        ? `+${isPlayer1 ? match.p2Score : match.p1Score}`
                                        : isPlayer1 ? match.p2Score : match.p1Score}
                                </p>
                            </Col>
                            <Col xs={5} className="d-flex align-items-center p-0 ms-1">
                                <p className="my-font m-0 text-start" style={{ fontSize: "1.2em" }}>
                                    {opponent.name} <br/> {opponent.surname}
                                </p>
                            </Col>
                            <Col xs={5} className="d-flex align-items-center p-0">
                                {opponentScores.map((score, index) => (
                                    <p
                                        key={index}
                                        className="me-2 mb-0"
                                        style={{
                                            fontWeight: setWinners[index] === 2 ? "bold" : "",
                                            color: setWinners[index] === 2 ? myGreen : "black",
                                        }}
                                    >
                                        {score}
                                    </p>
                                ))}
                            </Col>
                        </Row>
                    </Card.Body>
                </Card>
            </Col>
        </Col>
    );
};

export default MatchCard;
