import {useEffect, useState } from "react";
import {useNavigate } from "react-router-dom";
import { storage } from "../firebaseConfig";
import { Alert, Button, Col, Container, Form, Row } from "react-bootstrap";
import { getDownloadURL, ref } from "firebase/storage";
import './login.css'
import ScreenResize from "../utils/screen_resize";
import { useAuth } from "../AuthContext";
import LeftSide from "./login_left_side";

const Login = () => {
    const navigate = useNavigate();
    const { login } = useAuth();
    const [validated, setValidated] = useState(false);
    const [alert, setAlert] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [logoInvUrl, setLogoInvUrl] = useState('')
    const isScreenSmall = ScreenResize(900);

    useEffect(() => {
        const logoInvRef = ref(storage, 'gs://tennisclubcherasco.appspot.com/utils/logoTennisInverted.jpg');

        getDownloadURL(logoInvRef)
            .then((url) => {
                setLogoInvUrl(url);
            })
            .catch((error) => {
                console.error('Errore durante il recupero dell\'immagine:', error);
            });
    }, []);

    const onLogin = async (e: { preventDefault: () => void; }) => {
        e.preventDefault();
        try {
            await login(email, password);
            navigate("/main");
        } catch (error) {
            console.log(error)
            setAlert(true);
            setEmail('');
            setPassword('');
        }
    }

    return(
        <Container fluid className="p-0 d-flex" style={{height: '100vh'}}>
            <Row className="flex-grow-1 p-0 m-0" style={{height:"100%"}}>
                <LeftSide/>
                <Col className="p-0 d-flex flex-column" sm={isScreenSmall ? 12 : 6}>
                    <Row fluid className="d-flex p-0 m-0 flex-grow-1 align-items-center" style={{backgroundColor: isScreenSmall ? '#2f7157' : 'white'}}>
                        <Row className="align-items-center justify-content-center d-flex p-0 m-0">
                            <svg height="40" width="100%">
                                <line x1="0" y1="100%" x2="100%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 16 }} />
                            </svg>
                            <svg height="100" width="10">
                                <line x1="50%" y1="0%" x2="50%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 10 }} />
                            </svg>
                        </Row>
                        <Form noValidate className="" validated={validated} style={{width:"100%"}} onSubmit={onLogin}>
                            <Col className="d-flex justify-content-center mx-5 mb-4">
                                {isScreenSmall ?
                                    <img src={logoInvUrl} className="img-fluid mt-3" style={{maxWidth: '150px', height: 'auto', objectFit: 'scale-down'}} />
                                    :
                                    <></>
                                }
                                <h1 className={isScreenSmall ? "mt-5 my-font" : "mt-2 my-font"} style={{color: isScreenSmall ? 'white' : '#2f7157'}}>
                                    Accedi con il tuo account
                                </h1>
                            </Col>

                            <Row className="justify-content-center mx-5 mt-3">
                                <Col sm={8}>
                                    {alert && <Alert className="mt-2 mb-5" variant='danger' onClose={() => setAlert(false)} dismissible>Credenziali errate, riprova.</Alert>}
                                    <Form.Group id="formBasicEmail">
                                        <Form.Label className="my-font" style={{color: isScreenSmall ? 'white' : '#2f7157'}}>Email</Form.Label>
                                        <Form.Control
                                            type="text"
                                            placeholder="Inserisci email"
                                            value={email}
                                            style={{
                                                borderRadius: "12px",
                                                border: "solid",
                                                borderWidth: "2px",
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}
                                            onChange={(e) => setEmail(e.target.value)}
                                            required
                                        />
                                    </Form.Group>
                                </Col>
                            </Row>
                            <Row className="justify-content-center mx-5 mt-3">
                                <Col sm={8}>
                                    <Form.Group className="mt-4" id="formBasicPassword">
                                        <Form.Label className="my-font" style={{color: isScreenSmall ? 'white' : '#2f7157'}}>Password</Form.Label>
                                        <Form.Control
                                            type="password"
                                            placeholder="Password"
                                            value={password}
                                            style={{
                                                borderRadius: "12px",
                                                border: "solid",
                                                borderWidth: "2px",
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}
                                            onChange={(e) => setPassword(e.target.value)}
                                            required
                                        />
                                    </Form.Group>
                                </Col>
                            </Row>
                            <Row className="justify-content-center mx-5 mt-3 mb-4">
                                <Col sm={8} className="d-flex justify-content-center">
                                    <Button className="my-button-login mt-4" variant="primary" type="submit"
                                            style={{
                                                width: '50%',
                                                minHeight: '40px',
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}>
                                        <h5 className="my-font" style={{ pointerEvents: "none" }}>
                                            Log In
                                        </h5>
                                    </Button>
                                </Col>
                            </Row>
                            <Row className="justify-content-center mx-5 mt-3 mb-4">
                                <Col sm={8} className="d-flex justify-content-center">
                                    <Button className="my-button-login" variant="primary"
                                            style={{
                                                width: '50%',
                                                minHeight: '40px',
                                                borderColor: isScreenSmall ? 'white' : '#2f7157'
                                            }}
                                            onClick={() => navigate("/register")}>
                                        <h5 className="my-font" style={{ pointerEvents: "none" }}>
                                            Registrati
                                        </h5>
                                    </Button>
                                </Col>
                            </Row>
                            {/*<Row className="justify-content-center mx-5 mt-3 mb-4">*/}
                            {/*    <Col sm={8} className="d-flex justify-content-center">*/}
                            {/*        <SpecialButton/>*/}
                            {/*    </Col>*/}
                            {/*</Row>*/}
                            <Row className="justify-content-center mx-5 mt-5">
                                <Col sm={4} className="d-flex justify-content-center">
                                    <p
                                        style={{
                                            color: isScreenSmall ? 'white' : '#2f7157',
                                            cursor: 'pointer',
                                            textDecoration: 'underline',
                                            textAlign: 'center'
                                        }}
                                        onClick={() => navigate("/login/reset")}
                                    >
                                        Password dimenticata?
                                    </p>
                                </Col>
                            </Row>
                        </Form>
                        <Row className="align-items-center justify-content-center d-flex p-0 m-0">
                            <svg height="100" width="10">
                                <line x1="50%" y1="0%" x2="50%" y2="100%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 10 }} />
                            </svg>
                            <svg height="40" width="100%">
                                <line x1="0" y1="0%" x2="100%" y2="0%" style={{ stroke: isScreenSmall ? 'white' : '#2f7157', strokeWidth: 16 }} />
                            </svg>
                        </Row>
                    </Row>
                </Col>
            </Row>
        </Container>
    )
}

export default Login;