import {Player, Match} from "../utils/types";
import React, {useEffect, useState} from "react";
import {Button, Col, Row} from "react-bootstrap";
import "../account/account.css";
import {FaArrowLeft, FaArrowRight} from "react-icons/fa";
import {getH2HMatches} from "../utils/get_data";
import MatchCard from "../account/match_card";
import {wait} from "@testing-library/user-event/dist/utils";
import H2HMatchCard from "./h2h_match_card";

interface H2HLastMatchesProps {
    p1: Player;
    p2: Player;
}

const H2HLastMatches: React.FC<H2HLastMatchesProps> = ({ p1, p2 }) => {
    const [matches, setMatches] = useState<Match[]>([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const fetchMatches = async () => {
            setLoading(true);
            try {
                const result = await getH2HMatches(p1.uid, p2.uid);
                console.log(result);
                setMatches(result);
            } catch (error) {
                console.error("Errore nel recupero delle partite:", error);
                setMatches([]);
            } finally {
                setLoading(false);
            }
        };

        fetchMatches();
    }, [p1, p2]);


    const handleNext = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === matches.length - 1 ? 0 : prevIndex + 1
        );
    };

    const handlePrev = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === 0 ? matches.length - 1 : prevIndex - 1
        );
    };

    if(matches.length > 0) {
        return (
            <Row className="p-0 mx-0">
                <Row className="d-flex justify-content-center mx-0">
                    <h2 className="my-font">
                        Ultime partite giocate
                    </h2>
                </Row>
                <Col className="slider-container">
                    <Button className="p-0 circle-btn my-button arrow left" onClick={handlePrev}>
                        <FaArrowLeft/>
                    </Button>
                    <Col className="slider">
                        <Col
                            className="slider-inner"
                            style={{
                                transform: `translateX(-${currentIndex * 100}%)`,
                            }}
                        >
                            {matches.map((item) => (
                                <H2HMatchCard match={item} player1={p1} player2={p2}/>
                            ))}
                        </Col>
                    </Col>
                    <Button className="p-0 circle-btn my-button arrow right" onClick={handleNext}>
                        <FaArrowRight/>
                    </Button>
                </Col>
            </Row>
        )
    } else if (!loading){
        return (
            <Row className="p-0 mx-0">
                <Row className="d-flex justify-content-center mx-0">
                    <h2 className="my-font">
                        Ultime partite giocate
                    </h2>
                </Row>
                <Row className="d-flex justify-content-center mx-0 my-4">
                    <h4 className="my-font">
                        {p1.name} {p1.surname} e {p2.name} {p2.surname} non hanno ancora giocato alcuna partita
                    </h4>
                </Row>
            </Row>
        )
    } else {
        return (
            <></>
        )
    }
}

export default H2HLastMatches;