import { FaUserCircle } from "react-icons/fa"

const AccountIcon = ({ size, color, isInverted }: { size: number, color: string, isInverted: boolean }) => {
    return (
            <FaUserCircle style={{
                width: size + 'px',
                height:'auto',
                backgroundColor: isInverted ? "white" : color,
                color: isInverted ? color: 'white',
                objectFit: 'scale-down',
                border: 'solid',
                borderWidth: '3px',
                borderRadius: '50%',
                borderColor: isInverted ? 'white' : color}}
            />
    )
}

export default AccountIcon;