import {Player, PlayerStats, Match} from "../utils/types";
import React, {useEffect, useState} from "react";
import {Button, Card, Col, Row} from "react-bootstrap";
import "./account.css";
import {FaArrowLeft, FaArrowRight} from "react-icons/fa";
import {getPlayerMatches} from "../utils/get_data";
import MatchCard from "./match_card";
import {myGreen} from "../utils/utility";

interface PlayerLastMatchesProps {
    player: Player;
}

const PlayerLastMatches: React.FC<PlayerLastMatchesProps> = ({ player }) => {
    const [matches, setMatches] = useState<Match[]>([]);
    const [currentIndex, setCurrentIndex] = useState(0);

    useEffect(() => {
        const fetchMatches = async () => {
            const result = await getPlayerMatches(player.uid);
            setMatches(result);
        };

        fetchMatches();
    }, []);

    const handleNext = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === matches.length - 1 ? 0 : prevIndex + 1
        );
    };

    const handlePrev = () => {
        setCurrentIndex((prevIndex) =>
            prevIndex === 0 ? matches.length - 1 : prevIndex - 1
        );
    };

    if(matches.length > 0) {
        return (
            <Card className="my-shadow" style={{borderRadius: "15px"}}>
                <Card.Title className="d-flex align-items-center justify-content-center" style={{height: "60px", borderTopRightRadius: "15px", borderTopLeftRadius: "15px", backgroundColor: "#2f7157", color: "white"}}>
                    <h2 className="my-font">
                        Ultime partite giocate
                    </h2>
                </Card.Title>
                <Card.Body className="p-0">
                    <Row className="p-0 mx-0">
                        <Col className="slider-container">
                            <Button className="p-0 circle-btn my-button arrow left" onClick={handlePrev}>
                                <FaArrowLeft/>
                            </Button>
                            <Col className="slider">
                                <Col
                                    className="slider-inner"
                                    style={{
                                        transform: `translateX(-${currentIndex * 100}%)`,
                                    }}
                                >
                                    {matches.map((item) => (
                                        <MatchCard match={item} player={player}/>
                                    ))}
                                </Col>
                            </Col>
                            <Button className="p-0 circle-btn my-button arrow right" onClick={handleNext}>
                                <FaArrowRight/>
                            </Button>
                        </Col>
                    </Row>
                </Card.Body>
            </Card>
        )
    } else {
        return (
            <Card className="my-shadow" style={{borderRadius: "15px"}}>
                <Card.Title className="d-flex align-items-center justify-content-center" style={{height: "60px", borderTopRightRadius: "15px", borderTopLeftRadius: "15px", backgroundColor: myGreen, color: "white"}}>
                    <h2 className="my-font">
                        Ultime partite giocate
                    </h2>
                </Card.Title>
                <Card.Body className="p-0">
                    <h4 className="my-font my-4">
                        {player.name} {player.surname} non ha ancora giocato alcuna partita
                    </h4>
                </Card.Body>
            </Card>
        )
    }
}

export default PlayerLastMatches