import { Player } from "../utils/types";
import React, { useEffect, useState } from "react";
import { fetchProfileImage } from "../utils/get_data";
import { ImageHandler } from "../utils/image_handler";
import { myGreen } from "../utils/utility";
import { useNavigate } from "react-router-dom";
import { Card, Col, Container, Row } from "react-bootstrap";

interface TableEntryProps {
    player: Player;
    isScreenSmall: Boolean;
}

const TableEntry: React.FC<TableEntryProps> = ({ player, isScreenSmall }) => {
    const navigate = useNavigate();
    const [profileImageURL, setProfileImageURL] = useState<string | null>(null);

    useEffect(() => {
        if (player) {
            const loadProfileImage = async (imageURL: string) => {
                const downloadURL = await fetchProfileImage(imageURL);
                if(downloadURL) setProfileImageURL(downloadURL);
            }

            loadProfileImage(player.profileImage);
        } else {
            setProfileImageURL(null);
        }
    }, [player]);

    const rankingStyles: Record<number, { backgroundColor: string; borderColor: string; textColor: string; border: string }> = {
        1: { backgroundColor: "#ffe257", borderColor: "#C5A600", textColor: "#8B6508", border: "3px solid" }, // Oro
        2: { backgroundColor: "#cfcfcf", borderColor: "#A9A9A9", textColor: "#696969", border: "3px solid" }, // Argento
        3: { backgroundColor: "#ca864d", borderColor: "#A55A2C", textColor: "#5C3317", border: "3px solid" }, // Bronzo
    };

    const { backgroundColor, borderColor, textColor, border } = rankingStyles[player.ranking] || {
        backgroundColor: "white",
        borderColor: "rgba(0, 0, 0, 0.175)",
        textColor: myGreen,
        border: "1px solid "
    };

    return (
        <Card
            className="my-shadow mb-4"
            style={{
                width: "100%",
                height: "80px",
                borderRadius: "15px",
                backgroundColor,
                border: `${border} ${borderColor}`,
            }}
        >
            <Card.Body className="p-2">
                <Row className="d-flex align-items-center m-0" style={{ height: "100%" }}>
                    <Col className="p-0" xs={2}>
                        <Container
                            className="p-0 d-flex justify-content-center align-items-center"
                            style={{ fontSize: "1.2em", fontFamily: "Oswald", color: textColor }}
                        >
                            <h1 className="my-font m-0">{player.ranking !== null ? `#${player.ranking}` : "N/D"}</h1>
                        </Container>
                    </Col>
                    <Col className="p-0 ms-1" xs={2}>
                        <ImageHandler
                            size={60}
                            imageUrl={profileImageURL}
                            backColor={textColor}
                            onClick={() => navigate(`/account/${player.uid}`)}
                            isInverted={false}
                        />
                    </Col>
                    <Col className="p-0 ms-3 text-start my-font" xs={4}>
                        <h5 className="fw-normal" style={{ color: textColor }}>
                            {player.name} <span className="d-block d-sm-inline">{player.surname}</span>
                        </h5>
                    </Col>
                    <Col className="p-0" xs={3}>
                        <h3 className="my-font" style={{ color: textColor }}>
                            {player.score}pt
                        </h3>
                    </Col>
                </Row>
            </Card.Body>
        </Card>
    );
};

export default TableEntry;