import {Button, Card, Col, Container, Row} from "react-bootstrap";
import MyNavbar from "../navbar/navbar";
import React, { useEffect, useState } from "react";
import { FaUserCircle } from "react-icons/fa";
import { useParams, useNavigate } from "react-router-dom";
import { downloadImageFromStorage, fetchProfileImage, getStats, getUser } from "../utils/get_data";
import { useAuth } from "../AuthContext";
import ScreenResize from "../utils/screen_resize";
import EditButton from "./edit_button";
import H2HButton from "./H2HButton";
import { ImageHandler } from "../utils/image_handler";
import {Player, PlayerStats} from "../utils/types";
import PlayerStatistics from "./player_statistics";
import PlayerLastMatches from "./player_last_matches";
import "../App.css";
import {myGreen} from "../utils/utility";

function PlayerAccount() {
    const isScreenSmall = ScreenResize(1200)
    const navigate = useNavigate();
    const { userId } = useParams<{userId: string}>();
    const {currentUser, loading} = useAuth();
    const [user, setUser] = useState<Player>();
    const [stats, setStats] = useState<PlayerStats>();
    const [profileImageURL, setProfileImageURL] = useState<string | null>(null);

    useEffect(() => {
        const loadProfileImage = async (imageURL: string) => {
            const downloadURL = await fetchProfileImage(imageURL);
            if(downloadURL) setProfileImageURL(downloadURL);
        }

        const fetchUser = async () => {
            if (userId) {
                try {
                    const userData = await getUser(userId);
                    const statsData = await getStats(userId);
                    if (userData) setUser(userData);
                    if (statsData) setStats(statsData);

                    if (userData?.profileImage) {
                        await loadProfileImage(userData.profileImage);
                    }
                } catch (error) {
                    console.error("Error fetching user data:", error);
                }
            }
        };

        fetchUser();
    }, [userId]);

    if (user != null && stats != null) {
        return (
            <>
            <MyNavbar/>
            <Container fluid style={{minHeight: '78vh', width: "100%"}} className="d-flex justify-content-center text-center m-0 p-0">
                <Container fluid className="p-0">
                    <Row className="flex-grow-1 p-0 m-0" style={{width:"100%"}}>
                        <Col className="py-0 my-2 d-flex flex-column justify-content-center" sm={12}>

                            <Container className="d-flex justify-content-center mt-4">
                                <Card className="my-shadow" style={{width: isScreenSmall ? "100%" : "50%", height: "160px", backgroundColor: "#2f7157", borderRadius: "15px"}}>
                                    <Card.Body className="d-flex justify-content-between align-items-center">
                                        <Row className="mx-0 px-0" style={{height: "100%", width: "100%"}}>
                                            <Col className="d-flex flex-column align-items-center text-start justify-content-center p-0" style={{color: "white"}} xs={7}>
                                                <div className="my-font w-100 fs-3">{user.name}</div>
                                                <div className="my-font w-100 fs-1">{user.surname}</div>
                                            </Col>
                                            <Col className="d-flex align-items-center justify-content-center p-0" xs={5}>
                                                <ImageHandler size={90} imageUrl={profileImageURL} backColor={"#2f7157"} isInverted={true}/>
                                            </Col>
                                        </Row>
                                    </Card.Body>
                                </Card>
                            </Container>

                            <Container className="d-flex flex-column justify-content-center align-items-center mt-1">
                                <Row className="mt-3" style={{width: isScreenSmall ? "100%" : "50%"}}>
                                    <Col className="ps-0" xs={6}>
                                        <Card className="my-shadow" style={{height: "120px", borderRadius: "15px"}}>
                                            <Card.Body className="d-flex justify-content-start align-items-center">
                                                <Col className="d-flex flex-column align-items-center text-start justify-content-center p-0" style={{color: "black"}}>
                                                    <div className="my-font w-100 fs-4" style={{color: "#6d6d6d"}}>Ranking</div>
                                                    <div className="my-font w-100 fs-1" style={{color: myGreen, fontWeight: "bold"}}>
                                                        {user.ranking ? user.ranking : "N/D"}
                                                    </div>
                                                </Col>
                                            </Card.Body>
                                        </Card>
                                    </Col>
                                    <Col className="pe-0" xs={6}>
                                        <Card className="my-shadow" style={{height: "120px", borderRadius: "15px"}}>
                                            <Card.Body className="d-flex justify-content-start align-items-center">
                                                <Col className="d-flex flex-column align-items-center text-start justify-content-center p-0" style={{color: "black"}}>
                                                    <div className="my-font w-100 fs-4" style={{color: "#6d6d6d"}}>Score</div>
                                                    <div className="my-font w-100 fs-1" style={{color: myGreen, fontWeight: "bold"}}>
                                                        {user.score}
                                                    </div>
                                                </Col>
                                            </Card.Body>
                                        </Card>
                                    </Col>
                                </Row>
                                <Row className="mt-3" style={{width: isScreenSmall ? "100%" : "50%"}}>
                                    <Card className="my-shadow" style={{borderRadius: "15px"}}>
                                        <Card.Body>
                                            <Col className="d-flex flex-column align-items-center my-font">
                                                <div className="d-flex justify-content-between px-2 mb-1" style={{width: "100%"}}>
                                                    <span style={{color: "#6d6d6d"}}>Lato diritto</span>
                                                    <span style={{color: myGreen}}>{user.forehand}</span>
                                                </div>
                                                <div className="mx-5" style={{width: "100%", height: "1px", backgroundColor: "#cfcfcf"}}></div>
                                                <div className="d-flex justify-content-between mb-1 mt-2 px-2" style={{width: "100%"}}>
                                                    <span style={{color: "#6d6d6d"}}>Colpo preferito</span>
                                                    <span style={{color: myGreen}}>{user.bestShot}</span>
                                                </div>
                                                <div className="mx-5" style={{width: "100%", height: "1px", backgroundColor: "#cfcfcf"}}></div>
                                                <div className="d-flex justify-content-between mb-1 mt-2 px-2" style={{width: "100%"}}>
                                                    <span style={{color: "#6d6d6d"}}>Email</span>
                                                    <span style={{color: myGreen}}>{user.email}</span>
                                                </div>
                                                <div className="mx-5" style={{width: "100%", height: "1px", backgroundColor: "#cfcfcf"}}></div>
                                                <div className="d-flex justify-content-between mb-1 mt-2 px-2" style={{width: "100%"}}>
                                                    <span style={{color: "#6d6d6d"}}>Telefono</span>
                                                    <span style={{color: myGreen}}>{user.phone}</span>
                                                </div>
                                                <div className="mx-5" style={{width: "100%", height: "1px", backgroundColor: "#cfcfcf"}}></div>
                                            </Col>
                                        </Card.Body>
                                    </Card>
                                </Row>
                            </Container>

                            {currentUser.uid === userId ? <EditButton currentUserId={currentUser.uid}/> : <H2HButton player2={userId}/>}

                            <Col className="my-5" xs={12}>
                                <div className="mx-5" style={{height: "2px", backgroundColor: myGreen}}></div>
                            </Col>

                            <Container className="d-flex justify-content-center">
                                <PlayerStatistics stats={stats}/>
                            </Container>

                            <Col className="my-5" xs={12}>
                                <div className="mx-5" style={{height: "2px", backgroundColor: myGreen}}></div>
                            </Col>

                            <Container className="d-flex justify-content-center mb-5">
                                <PlayerLastMatches player={user}/>
                            </Container>
                        </Col>

                    </Row>
                </Container>
            </Container></>
        );
    }
    else {
        return (
            <></>
        )
    }
}

export default PlayerAccount;